package net.civeira.phylax.feature.observe.observedissue.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.observe.observedissue.domain.ObservedIssue;
import net.civeira.phylax.feature.observe.observedissue.domain.valueobject.TrackerUrlVO;

class TrackerUrlValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of tracker url of observed issue")
  void test_tracker_url_value_holder_assign_plain_value() {
    Object holder = new Object();
    TrackerUrlValueHolder<Object> value = new TrackerUrlValueHolder<>(holder);
    Assertions.assertSame(holder, value.trackerUrl("one"), "Setters must return the holder");
    Assertions.assertTrue(value.getTrackerUrlValue().isPresent(), "The plain value must be stored");
    Assertions.assertEquals("one", value.getTrackerUrl().orElse(null),
        "The plain value must be recovered");
    Assertions.assertSame(holder, value.trackerUrlNull(), "Setters must return the holder");
    Assertions.assertTrue(value.getTrackerUrlValue().isPresent(),
        "A null value object must be stored");
    Assertions.assertFalse(value.getTrackerUrl().isPresent(), "A null value must not have content");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of tracker url of observed issue")
  void test_tracker_url_value_holder_assign_value_object() {
    Object holder = new Object();
    TrackerUrlValueHolder<Object> value = new TrackerUrlValueHolder<>(holder);
    TrackerUrlVO vo = TrackerUrlVO.from("one");
    Assertions.assertFalse(value.getTrackerUrlValue().isPresent(), "A new holder must be empty");
    Assertions.assertSame(holder, value.trackerUrl(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getTrackerUrlValue().orElseThrow());
    Assertions.assertSame(holder, value.trackerUrl(Optional.empty()));
    Assertions.assertFalse(value.getTrackerUrlValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.trackerUrl(Optional.of(vo)));
    Assertions.assertSame(vo, value.getTrackerUrlValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of tracker url of observed issue against the original")
  void test_tracker_url_value_holder_read() {
    Object holder = new Object();
    TrackerUrlValueHolder<Object> value = new TrackerUrlValueHolder<>(holder);
    TrackerUrlVO vo = TrackerUrlVO.from("one");
    TrackerUrlVO other = TrackerUrlVO.from("one");
    ObservedIssue original = Mockito.mock(ObservedIssue.class);
    Mockito.when(original.getTrackerUrlValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readTrackerUrl(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNotNull(value.readTrackerUrl(Optional.empty(), fails),
        "Without value and original a null value is returned");
    Assertions.assertTrue(fails.isEmpty(), "An optional value is never reported as missing");
    value.trackerUrl(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readTrackerUrl(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readTrackerUrl(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of tracker url of observed issue")
  void test_tracker_url_value_holder_unset() {
    Object holder = new Object();
    TrackerUrlValueHolder<Object> value = new TrackerUrlValueHolder<>(holder);
    TrackerUrlVO vo = TrackerUrlVO.from("one");
    value.trackerUrl(vo);
    Assertions.assertSame(holder, value.unsetTrackerUrlIfMatches("trackerUrl_other"));
    Assertions.assertTrue(value.getTrackerUrlValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetTrackerUrlIfMatches("trackerUrl"));
    Assertions.assertFalse(value.getTrackerUrlValue().isPresent(),
        "The field name must clear the value");
    value.trackerUrl(vo);
    Assertions.assertSame(holder, value.unsetTrackerUrl());
    Assertions.assertFalse(value.getTrackerUrlValue().isPresent(), "Unset must clear the value");
  }
}
